import RPi.GPIO as GPIO
import spidev
import time
import datetime
import os
import signal
import sys
import adafruit_dht
import threading

# Configuration
DHT_PIN = 4  # BCM numbering
RELAY_PUMP = 17
RELAY_FAN = 27
RELAY_LIGHT = 22
LED_PIN = 25
MCP3008_CHANNEL = 0
SPI_CE0 = 8  # CS/CE0 pin
SPI_MOSI = 10
SPI_MISO = 9
SPI_SCLK = 11

# Global variables
last_temperature = None
last_humidity = None
last_command = None
last_sensor_read = None
last_actuator_command = None
sensor_present = True
watchdog_timer = None

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)
GPIO.setup(RELAY_PUMP, GPIO.OUT)
GPIO.setup(RELAY_FAN, GPIO.OUT)
GPIO.setup(RELAY_LIGHT, GPIO.OUT)
GPIO.setup(LED_PIN, GPIO.OUT)

# Initialize SPI
spi = spidev.SpiDev()
try:
    spi.open(0, 0)  # CE0
    spi.max_speed_hz = 1000000
except Exception as e:
    print(f"Error initializing SPI: {e}")
    spi = None

# Initialize DHT22 sensor
try:
    dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
except Exception as e:
    print(f"Error initializing DHT22 sensor: {e}")
    dht_device = None
    sensor_present = False

# Watchdog timer
def watchdog_reset():
    global watchdog_timer
    if watchdog_timer is not None:
        watchdog_timer.cancel()
    watchdog_timer = threading.Timer(600, watchdog_timeout)  # 10 minutes
    watchdog_timer.start()

def watchdog_timeout():
    print("Watchdog timeout! Restarting program.")
    os.execv(sys.executable, ['python'] + sys.argv)

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("Shutting down gracefully...")
    GPIO.cleanup()
    if spi:
        spi.close()
    sys.exit(0)

signal.signal(signal.SIGTERM, signal_handler)
signal.signal(signal.SIGINT, signal_handler)

# Initialize LED
GPIO.output(LED_PIN, GPIO.LOW)

# Function to set LED status
def set_led_status(status):
    if status == 'online':
        GPIO.output(LED_PIN, GPIO.HIGH)
    elif status == 'offline':
        GPIO.output(LED_PIN, GPIO.LOW)
    elif status == 'error':
        for _ in range(5):
            GPIO.output(LED_PIN, GPIO.HIGH)
            time.sleep(0.2)
            GPIO.output(LED_PIN, GPIO.LOW)
            time.sleep(0.2)
    elif status == 'synchronizing':
        for _ in range(5):
            GPIO.output(LED_PIN, GPIO.HIGH)
            time.sleep(0.2)
            GPIO.output(LED_PIN, GPIO.LOW)
            time.sleep(0.2)

# Function to read DHT22 sensor
def read_dht22_sensor():
    global last_temperature, last_humidity
    try:
        if dht_device:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                last_temperature = temperature
                last_humidity = humidity
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                return True
            else:
                print("Failed to read DHT22 sensor.")
                return False
        else:
            print("DHT22 sensor not initialized.")
            return False
    except Exception as e:
        print(f"Error reading DHT22 sensor: {e}")
        return False

# Function to read MCP3008 ADC
def read_mcp3008(channel):
    if spi is None:
        print("SPI not initialized.")
        return None
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        print(f"Error reading MCP3008 channel {channel}: {e}")
        return None

# Function to control the water pump
def control_pump(command):
    global last_command
    if command == 'on':
        GPIO.output(RELAY_PUMP, GPIO.HIGH)
        last_command = 'on'
        print("Water pump turned ON")
    elif command == 'off':
        GPIO.output(RELAY_PUMP, GPIO.LOW)
        last_command = 'off'
        print("Water pump turned OFF")
    else:
        print(f"Invalid command: {command}")
        last_command = command

# Function to control the ventilation fan
def control_fan(command):
    global last_command
    if command == 'on':
        GPIO.output(RELAY_FAN, GPIO.HIGH)
        last_command = 'on'
        print("Ventilation fan turned ON")
    elif command == 'off':
        GPIO.output(RELAY_FAN, GPIO.LOW)
        last_command = 'off'
        print("Ventilation fan turned OFF")
    else:
        print(f"Invalid command: {command}")
        last_command = command

# Function to control the supplemental lighting
def control_light(command):
    global last_command
    if command == 'on':
        GPIO.output(RELAY_LIGHT, GPIO.HIGH)
        last_command = 'on'
        print("Supplemental lighting turned ON")
    elif command == 'off':
        GPIO.output(RELAY_LIGHT, GPIO.LOW)
        last_command = 'off'
        print("Supplemental lighting turned OFF")
    else:
        print(f"Invalid command: {command}")
        last_command = command

# Function to process the command
def process_command(command):
    global last_sensor_read, last_actuator_command
    if command == 'read_sensor':
        if last_sensor_read:
            print(f"Last sensor read: Temperature={last_temperature:.1f}°C, Humidity={last_humidity:.1f}%")
        else:
            print("No sensor data available.")
    elif command == 'control_pump':
        control_pump('on')
    elif command == 'control_fan':
        control_fan('on')
    elif command == 'control_light':
        control_light('on')
    elif command == 'control_pump_off':
        control_pump('off')
    elif command == 'control_fan_off':
        control_fan('off')
    elif command == 'control_light_off':
        control_light('off')
    elif command == 'read_mcp3008':
        if spi:
            soil_moisture = read_mcp3008(MCP3008_CHANNEL)
            if soil_moisture is not None:
                print(f"Soil moisture level: {soil_moisture}")
            else:
                print("Failed to read soil moisture level.")
        else:
            print("SPI not initialized.")
    elif command == 'set_led_status':
        if len(sys.argv) > 2:
            status = sys.argv[2]
            set_led_status(status)
        else:
            print("Usage: set_led_status <status>")
    elif command == 'watchdog_reset':
        watchdog_reset()
    elif command == 'watchdog_timeout':
        watchdog_timeout()
    elif command == 'exit':
        print("Exiting program.")
        GPIO.cleanup()
        if spi:
            spi.close()
        sys.exit(0)
    else:
        print(f"Invalid command: {command}")

# Main loop
def main():
    global last_sensor_read, last_actuator_command
    watchdog_reset()
    try:
        while True:
            if read_dht22_sensor():
                last_sensor_read = datetime.datetime.now()
                if last_command:
                    control_light(last_command)
                    last_actuator_command = 'light'
                last_command = None

            if last_sensor_read and (datetime.datetime.now() - last_sensor_read).total_seconds() > 300:
                print("Sensor read timeout.")
                last_sensor_read = None

            time.sleep(10)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        if spi:
            spi.close()
        set_led_status('offline')

if __name__ == "__main__":
    main()

