#!/usr/bin/env python3

"""
ADS1115 16-bit ADC Demo for Raspberry Pi.

Reads analog values from an ADS1115 ADC over I2C using a functional approach.
"""

import time
import sys
import smbus2 as smbus
from functools import partial

# Constants
ADS1115_I2C_ADDR = 0x48  # Default I2C address (ADDR pin tied to GND)
I2C_BUS_NUMBER = 1       # I2C bus number on Raspberry Pi
PGA_GAIN = 4096          # Programmable gain amplifier gain (e.g., +/- 4.096V)
DATA_RATE = 128          # Data rate in samples per second (SPS)
FULL_SCALE_VOLTAGE = 4.096 # Full-scale voltage range for the given gain

# Functional building blocks

def _create_i2c_bus(bus_number, address):
    """Creates and opens an I2C bus."""
    try:
        bus = smbus.SMBus(bus_number)
        bus.write_byte_data(address, 0x01, 0x83)  # Power on the ADC
        return bus
    except Exception as e:
        print(f"Error creating I2C bus: {e}")
        sys.exit(1)

def _create_i2c_message(address, config_bits):
    """Creates an I2C message for configuration."""
    config = ((config_bits >> 4) & 0x0F) | ((config_bits << 2) & 0x60)
    return [0x01, (config << 6) | 0x00, 0x00]

def _read_adc_raw(bus, address, channel):
    """Reads raw ADC data from a specified channel."""
    config_bits = (channel << 12) | 0x8000 | 0x4000  # Single-ended, GND ref, PGA gain
    message = _create_i2c_message(address, config_bits)
    try:
        bus.write_i2c_block_data(address, 0x01, message)
        start_time = time.time()
        while True:
            status = bus.read_byte_data(address, 0x00)
            if (status & 0x01) == 0:
                break
            if time.time() - start_time > 0.1:  # Timeout
                print(f"Error: Conversion timed out on channel {channel}")
                return None
            time.sleep(0.001) # Small delay to prevent busy-waiting
        return bus.read_i2c_block_data(address, 0x02, 2)
    except Exception as e:
        print(f"Error reading ADC: {e}")
        return None

def _convert_to_signed_int(raw_data):
    """Converts raw ADC data to a signed 16-bit integer."""
    if raw_data is None:
        return None
    return int.from_bytes(raw_data, byteorder='big', signed=True)

def _convert_to_voltage(raw_int, gain):
    """Converts a signed integer to a voltage value."""
    if raw_int is None:
        return None
    return raw_int * (FULL_SCALE_VOLTAGE / 2**16)

def read_channel(bus, address, channel):
    """Reads voltage from a single ADC channel."""
    raw_data = _read_adc_raw(bus, address, channel)
    signed_int = _convert_to_signed_int(raw_data)
    voltage = _convert_to_voltage(signed_int, PGA_GAIN)
    return voltage

def read_all_channels(bus, address):
    """Reads voltage from all ADC channels."""
    read_channel_func = partial(read_channel, bus, address)
    return [read_channel_func(i) for i in range(4)]

def main():
    """Main function to demonstrate ADC reading."""
    try:
        bus = _create_i2c_bus(I2C_BUS_NUMBER, ADS1115_I2C_ADDR)
        while True:
            voltages = read_all_channels(bus, ADS1115_I2C_ADDR)
            print("| {0:>5} | {1:>5} | {2:>5} | {3:>5} |".format(*[f"{val:5.2f}" if val is not None else "----" for val in voltages]))
            time.sleep(0.05)
    except KeyboardInterrupt:
        print("Exiting...")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        if 'bus' in locals():
            bus.close()

if __name__ == "__main__":
    main()

