# Raspberry Pi QR Code Scanner for STEM Education
# Uses picamera2 to capture a frame and pyzbar to decode QR codes

import time
import cv2
from pyzbar.pyzbar import decode
from picamera2 import Picamera2

def initialize_camera():
    """Initialize the Raspberry Pi CSI camera."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
        camera.start()
        time.sleep(1)
        return camera
    except Exception as e:
        print(f"Camera initialization error: {e}")
        return None

def capture_frame(camera):
    """Capture a single frame from the CSI camera."""
    try:
        return camera.capture_array()
    except Exception as e:
        print(f"Frame capture error: {e}")
        return None

def decode_qr_code(frame):
    """Decode QR codes in a frame using pyzbar."""
    try:
        decoded_objects = decode(frame)
        return decoded_objects
    except Exception as e:
        print(f"QR code decoding error: {e}")
        return []

def main():
    """Main function to run the QR code scanner."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        frame = capture_frame(camera)
        if frame is None:
            return

        decoded_objects = decode_qr_code(frame)

        if decoded_objects:
            print('QR code detected!')
            # Optionally display the decoded data using OpenCV
            cv2.imshow("QR Code", frame)
            cv2.waitKey(1)
            print(decoded_objects[0].data.decode("utf-8"))
        else:
            print("No QR code detected.")

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        # Ensure the camera is released
        if camera:
            camera.stop()
            camera.close()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

