    try:
        GPIO.output(LIGHTS_PIN, GPIO.HIGH)
        lights_state = True
        logging.info("Lights turned ON.")
    except Exception as e:
        logging.error(f"Failed to turn lights ON: {e}")

def turn_lights_off():
    global lights_state
    try:
        GPIO.output(LIGHTS_PIN, GPIO.LOW)
        lights_state = False
        logging.info("Lights turned OFF.")
    except Exception as e:
        logging.error(f"Failed to turn lights OFF: {e}")

def read_temperature():
    global last_temperature
    try:
        if dht_device:
            temperature = dht_device.temperature
            if temperature is not None:
                last_temperature = temperature
                logging.info(f"Temperature: {temperature:.2f}°C")
            else:
                logging.warning("Failed to read temperature from DHT sensor.")
        else:
            # Simulate temperature reading
            import random
            last_temperature = random.uniform(15, 35)
            logging.info(f"Simulated Temperature: {last_temperature:.2f}°C")
    except Exception as e:
        logging.error(f"Failed to read temperature: {e}")

def read_humidity():
    global last_humidity
    try:
        if dht_device:
            humidity = dht_device.humidity
            if humidity is not None:
                last_humidity = humidity
                logging.info(f"Humidity: {humidity:.2f}%")
            else:
                logging.warning("Failed to read humidity from DHT sensor.")
        else:
            # Simulate humidity reading
            import random
            last_humidity = random.uniform(30, 70)
            logging.info(f"Simulated Humidity: {last_humidity:.2f}%")
    except Exception as e:
        logging.error(f"Failed to read humidity: {e}")

def take_picture():
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture_file(filename)
        logging.info(f"Picture saved as {filename}")
    except Exception as e:
        logging.error(f"Failed to take picture: {e}")

def process_voice_command(audio):
    try:
        # Listen for the wake word "Greenhouse"
        if "Greenhouse" in audio.data:
            logging.info("Wake word detected.")
            command = audio.data.split("Greenhouse ")[1].strip()
            logging.info(f"Command received: {command}")
            return command.lower()
        else:
            logging.info("Wake word not detected.")
            return None
    except Exception as e:
        logging.error(f"Error processing voice command: {e}")
        return None

def main():
    try:
        while True:
            if recognizer and microphone:
                with microphone as source:
                    recognizer.adjust_for_ambient_noise(source)
                    audio = recognizer.listen(source, timeout=5) # Timeout after 5 seconds of silence
                command = process_voice_command(audio)

                if command:
                    if "turn on the lights" in command:
                        turn_lights_on()
                    elif "turn off the lights" in command:
                        turn_lights_off()
                    elif "what is the temperature" in command:
                        read_temperature()
                    elif "take a picture" in command:
                        take_picture()
                    else:
                        logging.warning(f"Unknown command: {command}")
            else:
                # Simulate voice command processing
                import random
                commands = ["turn on the lights", "turn off the lights", "what is the temperature", "take a picture"]
                command = random.choice(commands)
                logging.info(f"Simulated voice command: {command}")

            time.sleep(1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Exiting program.")
        if camera:
            camera.close()
        if recognizer:
            recognizer.cleanup()
        GPIO.cleanup()

if __name__ == "__main__":
    main()

