# Configure logging
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
logger = logging.getLogger(__name__)

class StreamingOutput(StreamingHandler):
    """Handles streaming output for the Picamera2."""

    def __init__(self, picam2: Picamera2, config: StreamingConfig):
        super().__init__()
        self.picam2 = picam2
        self.config = config
        self.frame_buffer = MappedArray(self.picam2, "main")
        self.loop = asyncio.get_event_loop()
        self.encoder = None
        self.motion_detector = None
        self.stream_task = None
        self.running = False
        self.frame_buffer_lock = asyncio.Lock()

    def _initialize_encoder(self) -> None:
        """Initializes the H.264 encoder."""
        self.encoder = H264Encoder(1000000)
        self.encoder.configure(self.config.bitrate)

    def _initialize_motion_detector(self, config: CameraConfig) -> None:
        """Initializes the motion detector."""
        self.motion_detector = MotionDetector(config.roi, config.sensitivity)

    def _stream_loop(self) -> None:
        """Continuously streams video frames."""
        try:
            self._initialize_encoder()
            self._initialize_motion_detector(self.config.camera_config)

            while self.running:
                try:
                    frame_data = self.picam2.capture_array(self.frame_buffer)
                    if frame_data is None:
                        logger.warning("Failed to capture frame data.")
                        continue

                    if detect_motion(self.motion_detector, self.frame_buffer_lock, self.frame_buffer, frame_data):
                        self.loop.call_soon_threadsafe(self._broadcast_frame, frame_data)
                except Exception as e:
                    logger.error(f"Error in streaming loop: {e}")
                    break
                finally:
                    self.frame_buffer.array[:] = 0
        except Exception as e:
            logger.error(f"Failed to start streaming: {e}")
        finally:
            self.cleanup()

    def _broadcast_frame(self, frame_data: np.ndarray) -> None:
        """Broadcasts a frame via the streaming handler."""
        if self.config.jpeg_quality is not None:
            frame_bytes = cv2.imencode(
                ".jpg", frame_data, [int(cv2.IMWRITE_JPEG_QUALITY) for _ in range(1)]
            )[1]
        else:
            frame_bytes = frame_data.tobytes()

        if frame_bytes:
            try:
                self.loop.call_soon_threadsafe(self.config.streaming_handler.broadcast, frame_bytes)
            except Exception as e:
                logger.error(f"Error in streaming broadcast: {e}")

    async def start_streaming(self) -> None:
        """Starts the streaming loop in the event loop."""
        try:
            self.running = True
            self.loop.create_task(self._stream_loop())
        except Exception as e:
            logger.error(f"Failed to start streaming task: {e}")
            self.running = False

    def stop(self) -> None:
        """Stops the streaming loop and releases resources."""
        self.running = False
        self.cleanup()

    def cleanup(self) -> None:
        """Releases camera and encoder resources."""
        if self.encoder is not None:
            self.encoder.close()
            self.encoder = None
        if self.picam2 is not None:
            self.picam2.stop()
