from PIL import Image, ImageOps
import time
import logging
import os
import signal
import contextlib

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class Frame:
    """Represents a single frame in an animated GIF with lazy loading."""

    def __init__(self, image, duration=0, loop=0):
        """Initialize Frame with image, duration, and loop count."""
        self.image = image
        self.duration = duration
        self.loop = loop

    def advance(self):
        """Advance the frame index, looping if necessary."""
        self.loop -= 1
        if self.loop < 0:
            self.loop = self.image.info.get('loop', 0)  # Default to infinite if not specified
            if self.loop == 0:
                logging.warning("Frame's loop count is zero, stopping playback.")
                return False  # Indicate end of animation
            logging.info(f"Re-enqueued frame {self.image.filename} for further processing.")
            return False  # Re-enqueue for lazy loading
        return True # Continue playing

    def duration_remaining(self):
        """Calculate remaining duration for the frame."""
        return max(0, self.duration - (time.monotonic() - self.start_time)) / 1000

    def start_time(self):
        """Return the start time of the frame."""
        return time.monotonic()

class AnimatedGif:
    """
    A class to manage and display animated GIFs on a display,
    with robust error handling, performance optimizations, and
    comprehensive logging.
    """

    def __init__(self, display, width=None, height=None, folder=None):
        """Initialize AnimatedGif with display, dimensions, and folder."""
        self.display = display
        self._is_running = True
        self.frame_count = 0
        self.loop_count = 0
        self.current_frame = None
        self.current_file = None
        self.duration = 0
        self.folder = folder
        self.files = []

        # Register signal handler for graceful shutdown
        signal.signal(signal.SIGINT, self.stop)
        signal.signal(signal.SIGTERM, self.stop)

        self._load_files(folder)
        self.preload()

    def _load_files(self, folder):
        """Load GIF files from the specified folder."""
        if folder is not None:
            try:
                for filename in os.listdir(folder):
                    filepath = os.path.join(folder, filename)
                    if os.path.isfile(filepath) and filename.lower().endswith(('.gif', '.GIF')):
                        try:
                            with Image.open(filepath) as img:
                                if img.is_animated:
                                    self.files.append((filepath, img))
                                else:
                                    logging.warning(f"File {filepath} is not an animated GIF.")
                            logging.info(f"Loaded GIF file: {filepath}")
                        except Exception as e:
                            logging.error(f"Error loading file {filepath}: {e}")
            except FileNotFoundError:
                logging.error(f"Folder not found: {folder}")
                raise FileNotFoundError(f"Folder not found: {folder}")
            except Exception as e:
                logging.error(f"Error loading files from folder {folder}: {e}")
                raise

    def preload(self):
        """Preload and process frames for the next animation."""
        if not self.files:
            logging.warning("No GIF files loaded.  Call load_files() first.")
            return

        try:
            logging.info("Preloading animated GIF...")
            self.current_file, self.current_img = self.files[0]
            self.duration = self.current_img.info.get('duration', 0)
            self.loop_count = self.current_img.info.get('loop', 0)
            self.current_frame = Frame(self.current_img)

            with contextlib.closing(Image.open(self.current_file)) as image:
                for frame in ImageList(image):
                    self.current_frame = Frame(frame, self.duration, self.loop_count)
                    yield self.current_frame # Return frame for display.display(frame.image)

        except Exception as e:
            logging.error(f"Error preloading GIF: {e}")
            self.current_file = None
            self.current_frame = None
            self.loop_count = 0
            self.duration = 0

    def play(self):
        """Play the current animation."""
        if not self.files:
            logging.warning("No GIF files loaded.  Call load_files() first.")
            return False

        try:
            logging.info("Playing animated GIF...")
            self.frame_count = 0
            self.loop_count = self.files[0][1].info.get('loop', 0) # Get loop count from first file
            self.current_file, self.current_img = self.files[0]
            self.duration = self.current_img.info.get('duration', 0)

            while self._is_running and self.frame_count < self.loop_count:
                if self.current_frame.advance():
                    break # Frame advancement indicates end of animation or loop completion

                try:
                    start_time = self.current_frame.start_time()
                    elapsed_time = self.current_frame.duration_remaining()
                    sleep_time = max(0, self.current_frame.duration() - elapsed_time)

                    if elapsed_time > 0:
                        self.display.display(self.current_frame.image) # Display the frame
                        logging.debug(f"Displayed frame from {self.current_file}. Remaining time: {elapsed_time:.2f}s")
                    else:
                        logging.debug(f"Frame from {self.current_file} completed ahead of schedule.")

                    time.sleep(sleep_time)
                    self.frame_count += 1

                except Exception as e:
                    logging.error(f"Error displaying frame: {e}")
                    break # Stop animation on error

            return True # Animation completed successfully

        except Exception as e:
            logging.error(f"Error playing GIF: {e}")
            return False # Animation failed

    def advance(self):
        """Advance to the next animation (if any)."""
        if not self.files:
            logging.warning("No GIF files loaded.  Call load_files() first.")
            return False

        try:
            if self.current_file is not None:
                self.current_frame.advance()
                if self.current_frame.advance():
                    self.current_file, self.current_img = self.files.pop(0)
                    if not self.files:
                        logging.warning("No more GIF files to animate.")
                        self.current_file = None
                        self.current_frame = None
                    else:
                        self.preload() # Reload preloaded frames
                        self.play() # Start playing the next animation
                    return True
                return False # Still in the same animation
            return False # No current animation

        except Exception as e:
            logging.error(f"Error advancing animation: {e}")
            return False

    def run(self):
        """Continuously play the current animation."""
        while self._is_running:
            if self.play():
                self.advance() # Advance to the next animation if the current one completed
            time.sleep(0.1) # Prevent busy-waiting

        logging.info("Animation playback stopped.")

    def stop(self, signum=None, frame=None):
        """Stop animation playback gracefully."""
        logging.info("Stopping animation playback...")
        self._is_running = False
        self.advance() # Ensure the current animation loop terminates

