            with contextlib.closing(Image.open(self.current_file)) as image:
                for frame in ImageList(image):
                    self.current_frame = Frame(frame, self.duration, self.loop_count)
                    yield self.current_frame # Return frame for display.display(frame.image)

        except Exception as e:
            logging.error(f"Error preloading GIF: {e}")
            self.current_file = None
            self.current_frame = None
            self.loop_count = 0
            self.duration = 0

    def play(self):
        """Play the current animation."""
        if not self.files:
            logging.warning("No GIF files loaded.  Call load_files() first.")
            return False

        try:
            logging.info("Playing animated GIF...")
            self.frame_count = 0
            self.loop_count = self.files[0][1].info.get('loop', 0) # Get loop count from first file
            self.current_file, self.current_img = self.files[0]
            self.duration = self.current_img.info.get('duration', 0)

            while self._is_running and self.frame_count < self.loop_count:
                if self.current_frame.advance():
                    break # Frame advancement indicates end of animation or loop completion

                try:
                    start_time = self.current_frame.start_time()
                    elapsed_time = self.current_frame.duration_remaining()
                    sleep_time = max(0, self.current_frame.duration() - elapsed_time)

                    if elapsed_time > 0:
                        self.display.display(self.current_frame.image) # Display the frame
                        logging.debug(f"Displayed frame from {self.current_file}. Remaining time: {elapsed_time:.2f}s")
                    else:
                        logging.debug(f"Frame from {self.current_file} completed ahead of schedule.")

                    time.sleep(sleep_time)
                    self.frame_count += 1

                except Exception as e:
                    logging.error(f"Error displaying frame: {e}")
                    break # Stop animation on error

            return True # Animation completed successfully

        except Exception as e:
            logging.error(f"Error playing GIF: {e}")
            return False # Animation failed

    def advance(self):
        """Advance to the next animation (if any)."""
        if not self.files:
            logging.warning("No GIF files loaded.  Call load_files() first.")
            return False

        try:
            if self.current_file is not None:
                self.current_frame.advance()
                if self.current_frame.advance():
                    self.current_file, self.current_img = self.files.pop(0)
                    if not self.files:
                        logging.warning("No more GIF files to animate.")
                        self.current_file = None
                        self.current_frame = None
                    else:
                        self.preload() # Reload preloaded frames
                        self.play() # Start playing the next animation
                    return True
                return False # Still in the same animation
            return False # No current animation

        except Exception as e:
            logging.error(f"Error advancing animation: {e}")
            return False

    def run(self):
        """Continuously play the current animation."""
        while self._is_running:
            if self.play():
                self.advance() # Advance to the next animation if the current one completed
            time.sleep(0.1) # Prevent busy-waiting

        logging.info("Animation playback stopped.")

    def stop(self, signum=None, frame=None):
        """Stop animation playback gracefully."""
        logging.info("Stopping animation playback...")
        self._is_running = False
        self.advance() # Ensure the current animation loop terminates

class ImageList:
    """An iterator that yields each frame of a PIL Image sequence as a PIL Image."""

    def __init__(self, image):
        """Initialize ImageList with the target Image sequence."""
        self.image = image

    def __iter__(self):
        """Implement iterator protocol by returning the input image's sequence."""
        return iter(self.image.frame_sequence)

