#!/usr/bin/python3

import os
import time
import logging
from functools import partial
from typing import List, Tuple, Callable

import luma.core.interface.serial
import luma.lcd.device
import luma.lcd.panel
import luma.core.render
from PIL import Image, ImageOps

# Configure logging
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# Constants
SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
IMAGE_FOLDER = os.path.join(SCRIPT_DIR, "images")
FONT_PATH = os.path.join(SCRIPT_DIR, "fonts/FreeSans.ttf")
GIF_FOLDER = os.path.join(SCRIPT_DIR, "gifs")
DEFAULT_FONT = 16
FRAME_DELAY_MS = 100

# Initialize display
def init_display() -> luma.lcd.device.spi.SPI:
    """Initializes the ST7789 display using luma.lcd."""
    try:
        serial_interface = luma.core.interface.serial.i2c
        serial_port = 0x27
        rotation = 0
        width = 240
        height = 240

        display = luma.lcd.device.st7789(serial_interface, serial_port, rotation, width, height)
        logging.info("Display initialized successfully.")
        return display
    except Exception as e:
        logging.error(f"Failed to initialize display: {e}")
        raise


# Convert path to display image
def path_to_display_image(image_path: str) -> Image.Image:
    """Opens and converts an image path to a PIL Image object."""
    try:
        image = Image.open(image_path)
        return image
    except FileNotFoundError:
        logging.error(f"Image not found: {image_path}")
        raise
    except Exception as e:
        logging.error(f"Failed to open image {image_path}: {e}")
        raise


# Convert image to monochrome
def image_to_monochrome(image: Image.Image) -> Image.Image:
    """Converts a PIL Image object to monochrome (1-bit)."""
    return image.convert("1")


# Display image
def display_image(display: luma.lcd.device.spi.SPI, image: Image.Image) -> None:
    """Displays a PIL Image on the ST7789 display."""
    try:
        display.image(image)
    except Exception as e:
        logging.error(f"Failed to display image: {e}")
        raise


# Display text
def display_text(display: luma.lcd.device.spi.SPI, text: str, x: int, y: int, font_size: int) -> None:
    """Displays text on the ST7789 display using a PIL font."""
    try:
        font = luma.core.font.load_default(font_size)
        renderer = luma.lcd.device.st7789.pil_renderer(font, image_size=(240, 128))
        display.image(renderer.render_text(text, font=font, fill="white", x=x, y=y))
    except Exception as e:
        logging.error(f"Failed to display text: {e}")
        raise


# Convert frame to display image
def convert_frame_to_display_image(frame: bytes) -> Image.Image:
    """Converts raw frame data (bytes) into a PIL Image suitable for display."""
    try:
        image = Image.frombytes("RGB", (240, 240), frame)
        return image
    except Exception as e:
        logging.error(f"Failed to convert frame to display image: {e}")
        raise


# Convert frame to monochrome
def convert_frame_to_monochrome(frame: Image.Image) -> Image.Image:
    """Converts a PIL Image (RGB) to monochrome (1-bit)."""
    return frame.convert("1")


# Display frame
def display_frame(display: luma.lcd.device.spi.SPI, frame: Image.Image) -> None:
    """Displays a single frame on the ST7789 display."""
    try:
        display_image(display, frame)
    except Exception as e:
        logging.error(f"Failed to display frame: {e}")
        raise


# Display frames
def display_frames(display: luma.lcd.device.spi.SPI, frames: List[Image.Image], duration: int) -> None:
    """Displays a list of PIL Image frames on the ST7789 display with a delay."""
    try:
        for frame in frames:
            display_frame(display, frame)
            time.sleep(duration / 1000.0)
    except Exception as e:
        logging.error(f"Failed to display frames: {e}")
        raise


# Play GIF
def play_gif(display: luma.lcd.device.spi.SPI, gif_path: str, duration: int = 100) -> None:
    """Plays a GIF file on the ST7789 display."""
    try:
        with Image.open(gif_path) as gif:
            if not gif.is_animated:
                logging.warning(f"{gif_path} is not an animated GIF.")
                return

            # Use a functional approach to process each frame
            frames = [frame.copy() for frame in list(gif.getdata(unit='frame'))]  # Convert to RGB
            frames = [convert_frame_to_display_image(frame.tobytes()) for frame in frames]
            frames = [convert_frame_to_monochrome(frame) for frame in frames]

        logging.info(f"Found {len(frames)} frames in {gif_path}")

        # Display the frames in a loop
        while True:
            for frame in frames:
                display_frames(display, [frame], duration)

    except FileNotFoundError:
        logging.error(f"GIF file not found: {gif_path}")
    except Exception as e:
        logging.error(f"Failed to play GIF {gif_path}: {e}")


# Play all GIFs in the folder
def play_all_gifs(display: luma.lcd.device.spi.SPI, gif_folder: str) -> None:
    """Plays all GIF files found in the specified folder."""
    try:
        os.chdir(gif_folder)
        for filename in os.listdir(gif_folder):
            gif_path = filename
            if filename.endswith(".gif"):
                play_gif(display, gif_path, duration=FRAME_DELAY_MS)
                time.sleep(1)
    except FileNotFoundError:
        logging.error(f"GIF folder not found: {gif_folder}")
    except Exception as e:
        logging.error(f"Failed to play all GIFs: {e}")


def run_gif_player(display: luma.lcd.device.spi.SPI, gif_folder: str, duration: int = 100) -> None:
    """Runs the main loop for the animated GIF player."""
    try:
        while True:
            play_all_gifs(display, gif_folder)
    except KeyboardInterrupt:
        logging.info("Exiting program.")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Cleaning up resources.")
        if display:  # Check if display was initialized
            display.clear()


if __name__ == "__main__":
    try:
        display = init_display()
        run_gif_player(display, GIF_FOLDER)
    except Exception as e:
        logging.error(f"Program terminated with error: {e}")

