import time
from gpiozero import CPUTemperature

def read_cpu_temperature():
    """Read the CPU temperature and print it to the console."""
    try:
        # Instantiate the CPUTemperature object inside the try block
        cpu_temp = CPUTemperature()
        # Read the current temperature value
        current_temp = cpu_temp.temperature
        # Format the output to two decimal places
        print("CPU Temperature: {:.2f} °C".format(current_temp))
    except FileNotFoundError:
        print("Error: CPU temperature sensor not found.")
    except Exception as e:
        print("An unexpected error occurred: {}".format(e))

def main():
    """Main function to continuously read and print the CPU temperature."""
    try:
        while True:
            read_cpu_temperature()
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated")
        exit(0)
    except Exception as e:
        print("An unexpected error occurred: {}".format(e))
        exit(1)

if __name__ == "__main__":
    main()

