import serial
import time
import csv
import sys

# Serial port configuration for the temperature sensor
SERIAL_PORT = "/dev/ttyACM0"
BAUD_RATE = 115200
TIMEOUT = 1

# CSV log file path
LOG_FILE = "temperature_log.csv"


def configure_serial(port, baudrate, timeout):
    """Configure and return a serial port object."""
    try:
        return serial.Serial(port, baudrate, serial.EIGHTBITS, serial.PARITY_NONE, serial.STOPBITS_ONE, timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)


def read_temperature(serial_port):
    """Read a line from the serial port and return the temperature in Celsius."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Warning: Could not convert reading to float.")
        return None


def convert_to_fahrenheit(celsius_temperature):
    """Convert Celsius to Fahrenheit."""
    return celsius_temperature * 9/5 + 32


def log_temperature(log_file, timestamp, celsius, fahrenheit):
    """Append the temperature data to the CSV log file."""
    try:
        with open(log_file, "a", newline="") as csvfile:
            csv_writer = csv.writer(csvfile)
            csv_writer.writerow([timestamp, celsius, fahrenheit])
    except IOError as e:
        print(f"Error writing to log file: {e}")


def main():
    """Main function to read temperature and log data."""
    serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    # Write CSV header if the file is new
    try:
        with open(LOG_FILE, "r") as f:
            pass
    except FileNotFoundError:
        with open(LOG_FILE, "w", newline="") as csvfile:
            csv_writer = csv.writer(csvfile)
            csv_writer.writerow(["timestamp", "celsius", "fahrenheit"])

    try:
        while True:
            celsius_temp = read_temperature(serial_connection)
            if celsius_temp is not None:
                fahrenheit_temp = convert_to_fahrenheit(celsius_temp)
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                log_temperature(LOG_FILE, timestamp, celsius_temp, fahrenheit_temp)
                print(f"{timestamp}: Celsius={celsius_temp:.2f}, Fahrenheit={fahrenheit_temp:.2f}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        serial_connection.close()
        print("Serial port closed.")


if __name__ == "__main__":
    main()

