# -*- coding: utf-8 -*-
"""
Reads temperature and humidity from an AHT20 sensor on a Raspberry Pi 5.
Uses the adafruit_ahtx0 library over the I2C bus.
"""

import time
import board
import busio
import adafruit_ahtx0

# Configuration
I2C_ADDRESS = 0x38
READ_INTERVAL_SECONDS = 5

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the AHT20 sensor."""
    try:
        return adafruit_ahtx0.AHTx0(i2c_bus, address=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing AHT20 sensor: {e}")
        return None

def read_sensor_data(sensor_device):
    """Read temperature and humidity from the sensor."""
    try:
        temperature = sensor_device.temperature
        humidity = sensor_device.relative_humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def validate_data(temperature, humidity):
    """Validate temperature and humidity readings."""
    if temperature is None or humidity is None:
        return False
    if not -40 <= temperature <= 85:
        print(f"Warning: Invalid temperature reading: {temperature}°C")
        return False
    if not 0 <= humidity <= 100:
        print(f"Warning: Invalid humidity reading: {humidity}%")
        return False
    return True

def display_data(timestamp, temperature, humidity):
    """Print the sensor data to the console."""
    print(f"{timestamp} Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")

def main():
    """Main function to read and display temperature and humidity."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(sensor)
            if validate_data(temperature, humidity):
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                display_data(timestamp, temperature, humidity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        i2c_bus.deinit()

if __name__ == "__main__":
    main()

