    """Decorator for handling exceptions in command functions."""

    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            print(f"Error executing command: {e}")

    return wrapper


@handle_exception
def show_help():
    """Displays help information for commands."""
    print("Help: Displays help information")
    print("start : Starts logging data to a file")
    print("stop: Stops the server and exits")
    print("display: Displays the current contents of the log file")
    print("send <data>: Sends data using DOGProtocol (format: 'data_string speed_mhz')")
    print("write <data>: Writes data directly to the log file")
    print("exit: Stops the server and exits")


@handle_exception
def start(filename):
    """Starts logging data to a file."""
    global FILE_NAME, SERVER_STARTED
    if SERVER_STARTED:
        print("Server already started.")
        return
    FILE_NAME = filename
    try:
        with file_lock:
            # Create/open the file and write header if it doesn't exist
            with open(filename, 'a+') as f:
                import os
                if os.stat(filename).st_size == 0:
                    f.write("Log file\n")
                f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}]\n")

        # Start the receive thread
        receive_thread = threading.Thread(target=receive_data, daemon=True, name='Receive Thread')
        receive_thread.start()
        SERVER_STARTED = True

    except Exception as e:
        print(f"Error starting server: {e}")


# ... (rest of the functions: stop, display, send, write, help, and main loop)

def receive_data():
    """Continuously receives data and writes it to the log file."""
    global FILE_NAME, SERVER_STARTED
    while SERVER_STARTED:
        try:
            data = DOG.receive()  # Your custom receive function
            with file_lock:
                if data:  # Avoid writing empty data
                    with open(FILE_NAME, 'a+') as f:
                        f.write(data + "\n")
        except Exception as e:
            print(f"Error receiving data: {e}")
            break  # Exit the loop on receive error


def main():
    """Main function to run the server and handle user input."""
    global FILE_NAME, SERVER_STARTED
    signal.signal(signal.SIGINT, lambda *args: exit(0))  # Handle Ctrl+C
    signal.signal(signal.SIGTERM, lambda *args: exit(0))  # Handle termination signals

    while True:
        try:
