        """Handles connection status updates."""
        try:
            self.sub_con_list.append(content.get('connected', self.sub_con_list[-1]))
            logger.info(f"Connection status: {self.sub_con_list[-1]}")
        except Exception as e:
            logger.error(f"Error handling connection update: {e}")

