        """Handles modification status updates."""
        try:
            self.sub_mod_list.append(content.get('modified', self.sub_mod_list[-1]))
            logger.info(f"Modification status: {self.sub_mod_list[-1]}")
        except Exception as e:
            logger.error(f"Error handling modification update: {e}")

