                self.global_err_state = state
                logger.info(f"Error output set to: {state}")
        except Exception as e:
            logger.error(f"Error setting error output: {e}")

    def PID_controller(self, val: float) -> None:
        """Calculates and applies the PID controller output."""
        try:
            if self.global_err_state:
                out_val = self.K10CR1.update(val)
                logger.info(f"PID output: {out_val}")
                self.set_error_output(False)
        except Exception as e:
            logger.error(f"Error in PID controller: {e}")


