    """Main entry point for the application."""
    global ERR_TOG, ERR_STATE, ERR_ERR_STR, ERR_VAL_SET, ERR_VAL, TOGGLE_COUNT, SUB_CMD_LIST, SUB_KW_LIST, \
        TOGGLE_LIST, RECONFIG_VAL, RECONFIG_ERR, RECONFIG_ERR_STR, RECONFIG_ERR_LOG

