        subscribe(SUB_SOCK, 'CTL/EPICS/K10CR1/TOGGLE', lambda x: handle_subscription(SUB_SOCK, 'CTL/EPICS/K10CR1/TOGGLE', lambda x: None))
        subscribe(SUB_SOCK, 'CTL/EPICS/K10CR1/CON', lambda x: handle_subscription(SUB_SOCK, 'CTL/EPICS/K10CR1/CON', lambda x: None))
        subscribe(SUB_SOCK, 'CTL/EPICS/K10CR1/MOD', lambda x: handle_subscription(SUB_SOCK, 'CTL/EPICS/K10CR1/MOD', lambda x: None))
        subscribe(SUB_SOCK, 'CTL/EPICS/K10CR1/RET', lambda x: handle_subscription(SUB_SOCK, 'CTL/EPICS/K10CR1/RET', lambda x: None))

