                except zmq.ZMQError as e:
                    logger.error(f"ZMQ error in main loop: {e}")
                    time.sleep(1)  # Prevent busy-waiting
                else:
                    time.sleep(0.01)  # Prevent busy-waiting

            except KeyboardInterrupt:
                logger.info("Keyboard interrupt detected. Exiting.")
                break

            except Exception as e:
                logger.exception(f"Unexpected error in main loop: {e}")
                break

    except Exception as e:
        logger.exception(f"Fatal error during initialization: {e}")
    finally:
        logger.info("Cleaning up and exiting.")
        try:
            SUB_SOCK.close()
            REQUEST_SOCK.close()
            RECONFIG_SOCK.close()
        except Exception as e:
            logger.error(f"Error closing sockets: {e}")
        try:
            GPIO.cleanup()
        except RuntimeError as e:
            logger.error(f"GPIO cleanup failed (not running on a Pi?): {e}")
        except Exception as e:
            logger.error(f"Unexpected error during cleanup: {e}")


if __name__ == '__main__':
    pid_handler = PIDHandler(pid_params, global_err_state, global_val_set, global_val)
    main()

