#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi.

This module provides a robust and efficient interface to the DS1338 RTC
using the SMBus. It offers comprehensive error handling, detailed documentation,
and optimized performance for Raspberry Pi platforms.

Example Usage:
>>> rtc = DS1338()
>>> current_datetime = rtc.read_datetime()
>>> print(current_datetime)
>>> rtc.write_datetime(datetime.datetime(2024, 1, 1, 12, 0, 0))
"""

import smbus2
import time
import datetime
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) using the SMBus."""

    # Register addresses for the DS1338
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07
    REG_STATUS = 0x0F  # Added Status Register address

    def __init__(self, i2c_bus_number=1, device_address=0x68):
        """Initialize the DS1338 RTC driver.

        Args:
            i2c_bus_number (int): The I2C bus number (default: 1).
            device_address (int): The I2C address of the DS1338 (default: 0x68).

        Raises:
            IOError: If the device is not found at the specified address.
        """
        self.i2c_bus_number = i2c_bus_number
        self.device_address = device_address
        self._bus = None  # Initialize bus to None
        self._initialize()

    def _initialize(self):
        """Initialize the I2C bus and check if the device is present."""
        try:
            self._bus = smbus2.SMBus(self.i2c_bus_number)
            if not self._device_present():
                raise IOError(f"DS1338 not found at address {self.device_address:02X}")
            logger.info(f"DS1338 initialized successfully at address {self.device_address:02X}")
        except (smbus2.SMBusError, IOError) as e:
            logger.error(f"Failed to initialize DS1338: {e}")
            raise

    def _device_present(self):
        """Check if the DS1338 is connected at the specified address."""
        try:
            self._bus.read_byte(self.device_address)
            return True
        except (smbus2.SMBusError, IOError):
            return False

    def _bcd_to_int(self, bcd_value):
        """Decode a 2x4bit BCD to an integer."""
        try:
            return int(f"{bcd_value >> 4:01}{bcd_value & 0x0F:01}")
        except (TypeError, ValueError) as e:
            logger.error(f"Error converting BCD to int: {e}")
            return None

    def _int_to_bcd(self, integer_value):
        """Encode an integer to BCD format."""
        if not 0 <= integer_value <= 99:
            raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
        return (integer_value // 10 << 4) | (integer_value % 10)

    def _read_register(self, register):
        """Read a byte from the specified register."""
        if not 0 <= register <= 0x0F:  # Valid register range
            raise ValueError("Invalid register address.")
        try:
            return self._bus.read_byte_data(self.device_address, register)
        except (smbus2.SMBusError, IOError) as e:
            logger.error(f"Error reading register 0x{register:02X}: {e}")
            raise

    def _write_register(self, register, value):
        """Write a byte to the specified register."""
        if not 0 <= register <= 0x0F:  # Valid register range
            raise ValueError("Invalid register address.")
        try:
            self._bus.write_byte_data(self.device_address, register, value)
        except (smbus2.SMBusError, IOError) as e:
            logger.error(f"Error writing to register 0x{register:02X}: {e}")
            raise


    def read_all(self):
        """Read all time and date registers from the RTC."""
        try:
            year = self._bcd_to_int(self._read_register(self.REG_YEAR))
            month = self._bcd_to_int(self._read_register(self.REG_MONTH))
            date = self._bcd_to_int(self._read_register(self.REG_DATE))
            hours = self._bcd_to_int(self._read_register(self.REG_HOURS) & 0x3F) # Ensure 24-hour format
            minutes = self._bcd_to_int(self._read_register(self.REG_MINUTES))
            seconds = self._bcd_to_int(self._read_register(self.REG_SECONDS))
            day = self._bcd_to_int(self._read_register(self.REG_DAY))
            return year, month, date, day, hours, minutes, seconds
        except ValueError as e:
            logger.error(f"Error reading time and date: {e}")
            raise  # Re-raise for higher-level handling


    def read_datetime(self, century=21):
        """Read the current time and return a datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self.read_all()
            year = (century - 1) * 100 + year
            return datetime.datetime(year, month, date, hours, minutes, seconds)
        except ValueError as e:
            logger.error(f"Failed to create datetime object: {e}")
            raise

    def write_all(self, year=None, month=None, date=None, day=None, hours=None, minutes=None, seconds=None):
        """Write all time and date registers to the RTC."""

        if year is not None:
            self._write_register(self.REG_YEAR, self._int_to_bcd(year))
        if month is not None:
            self._write_register(self.REG_MONTH, self._int_to_bcd(month))
        if date is not None:
            self._write_register(self.REG_DATE, self._int_to_bcd(date))
        if day is not None:
            self._write_register(self.REG_DAY, self._int_to_bcd(day))
        if hours is not None:
            self._write_register(self.REG_HOURS, self._int_to_bcd(hours)) # Ensure 24-hour format
        if minutes is not None:
            self._write_register(self.REG_MINUTES, self._int_to_bcd(minutes))
        if seconds is not None:
            self._write_register(self.REG_SECONDS, self._int_to_bcd(seconds))


    def write_datetime(self, dt):
        """Write the given datetime object to the RTC."""
        if not isinstance(dt, datetime.datetime):
            raise TypeError("Input must be a datetime.datetime object.")

        try:
            self.write_all(
                year=dt.year % 100,
                month=dt.month,
                date=dt.day,
                day=dt.isoweekday(),
                hours=dt.hour,
                minutes=dt.minute,
                seconds=dt.second,
            )
        except ValueError as e:
            logger.error(f"Error writing datetime to RTC: {e}")
            raise

    def close(self):
        """Close the I2C bus connection."""
        if self._bus:
            try:
                self._bus.close()
                logger.info("I2C bus closed successfully.")
            except smbus2.SMBusError as e:
                logger.error(f"Error closing I2C bus: {e}")
            finally:
                self._bus = None  # Ensure self._bus is None

