import time
import logging
from gpiozero import LED

# Configure logging for the water flow monitor
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Serial port configuration for the water flow sensor
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1

# GPIO pin connected to the alert LED
ALERT_LED_PIN = 17

# Flow threshold in liters per minute
FLOW_THRESHOLD = 10.0

# Initialize the alert LED using gpiozero
alert_led = LED(ALERT_LED_PIN)

def configure_serial(port, baudrate, timeout):
    """Configure and return a serial port object."""
    try:
        return serial.Serial(port, baudrate, serial.EIGHTBITS, serial.PARITY_NONE, serial.STOPBITS_ONE, timeout=timeout)
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
        return None

def parse_flow_rate(raw_line):
    """Parse a raw serial line into a floating-point flow rate."""
    try:
        return float(raw_line)
    except ValueError:
        logging.warning(f"Invalid data received: {raw_line}")
        return None

def update_alert(flow_rate):
    """Drive the alert LED based on the flow rate."""
    if flow_rate > FLOW_THRESHOLD:
        alert_led.on()
    else:
        alert_led.off()

def main():
    """Main function to read flow data and trigger alerts."""
    serial_port = configure_serial(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if serial_port is None:
        return

    try:
        while True:
            try:
                raw_line = serial_port.readline().decode("utf-8", errors="ignore").strip()
                flow_rate = parse_flow_rate(raw_line)
                if flow_rate is not None:
                    logging.info(f"Flow rate: {flow_rate} L/min")
                    update_alert(flow_rate)
                time.sleep(1)
            except serial.SerialException as e:
                logging.error(f"Serial port error: {e}")
                break
            except Exception as e:
                logging.error(f"Unexpected error: {e}")
                break
    finally:
        serial_port.close()
        alert_led.close()
        logging.info("Resources released.")

if __name__ == "__main__":
    main()

