import serial
import time
import datetime
import os
import signal
import sys

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

# Global serial port object
serial_port = None

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        sys.exit(1)

def read_co2_concentration(serial_port):
    """Reads CO2 concentration from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return int(line)
        return None
    except ValueError:
        print("Error: Invalid data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None

def log_co2_reading(timestamp, co2_concentration, log_file):
    """Logs the CO2 reading to a file."""
    try:
        with open(log_file, 'a') as logfile:
            logfile.write(f"{timestamp}, {co2_concentration} ppm\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    print("Exiting program...")
    if serial_port:
        serial_port.close()
    sys.exit(0)

def main():
    """Main function to read CO2 concentration and log data."""
    global serial_port
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_port = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    try:
        while True:
            co2_value = read_co2_concentration(serial_port)
            if co2_value is not None:
                timestamp = datetime.datetime.now().isoformat()
                log_co2_reading(timestamp, co2_value, LOG_FILE)
                print(f"CO2: {co2_value} ppm at {timestamp}")
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if serial_port:
            serial_port.close()
        print("Program finished.")

if __name__ == "__main__":
    main()

