import serial
import time
import datetime

# Serial port configuration for the GPS module
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Log file path for storing GPS coordinates
LOG_FILE = 'gps_coordinates_log.txt'


def initialize_serial(port, baudrate, timeout):
    """Initialize and return a serial port object."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def parse_gps_data(raw_data):
    """Parse a GPGGA sentence and return latitude, longitude, and altitude."""
    try:
        if raw_data.startswith('$GPGGA'):
            parts = raw_data.split(',')
            if parts[6] == '1':
                latitude = parts[2]
                longitude = parts[4]
                altitude = parts[9]
                return latitude, longitude, altitude
    except Exception as e:
        print(f"Error parsing GPS data: {e}")
    return None, None, None


def log_coordinates(latitude, longitude, altitude, log_filepath):
    """Append the timestamped coordinates to the log file."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(log_filepath, 'a') as log_file:
            log_file.write(f"{timestamp}, {latitude}, {longitude}, {altitude}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def main():
    """Main function to read GPS data and log coordinates."""
    serial_port = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_port is None:
        return

    try:
        while True:
            try:
                raw_data = serial_port.readline().decode('ascii', errors='replace').strip()
            except serial.SerialException as e:
                print(f"Error reading from serial port: {e}")
                break

            latitude, longitude, altitude = parse_gps_data(raw_data)

            if latitude and longitude and altitude:
                print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m")
                log_coordinates(latitude, longitude, altitude, LOG_FILE)

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")

    finally:
        if serial_port and serial_port.is_open:
            serial_port.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

