from flask import Flask, Response, request, jsonify
import json
import time
import logging
import serial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

app = Flask(__name__)

# Configure serial port
try:
    ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
    logging.info("Serial port opened successfully.")
except serial.SerialException as e:
    logging.error(f"Failed to open serial port: {e}")
    ser = None

# Initialize data store
data_store = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "garden", "done": False}]


def get_instrument_version():
    """Queries the instrument for its version information via SCPI."""
    if ser is None:
        logging.error("Serial port not initialized.")
        return None

    try:
        ser.write(b'*IDN?\n')
        time.sleep(0.1)  # Allow time for the instrument to respond
        response = ser.read(1024).decode('utf-8', errors='ignore') # Read up to 1024 bytes
        logging.info(f"Instrument version: {response}")
        return response
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return None


@app.route('/version', methods=['GET'])
def version():
    """Returns the instrument version as HTML."""
    version_info = get_instrument_version()
    if version_info:
        return Response(version_info + '<br>', mimetype='text/html')
    else:
        return Response("Failed to retrieve instrument version.", mimetype='text/html', status=503)


@app.route('/getdata', methods=['GET'])
def get_data():
    """Returns the entire data store as JSON."""
    return jsonify(data_store)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_item(item_id):
    """Returns a specific item from the data store as JSON."""
    item = next((item for item in data_store if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        return Response("Item not found.", mimetype='text/html', status=404)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def post_item(item_id, name):
    """Appends a new item to the data store and returns the updated store as JSON."""
    new_id = data_store[-1]['id'] + 1 if data_store else 1
    new_item = {"id": new_id, "name": name, "done": False}
    data_store.append(new_item)
    return jsonify(data_store)


@app.route('/postjson', methods=['POST', 'GET'])
def post_json():
    """Accepts JSON data in the request body or as query parameters and adds a new item to the data store."""
    if request.method == 'POST':
        if "application/json" in request.headers.get("Content-Type", ""):
            try:
                j_data = request.get_json()
                new_id = data_store[-1]['id'] + 1 if data_store else 1
                j_data['id'] = new_id
                data_store.append(j_data)
                return jsonify(data_store)
            except json.JSONDecodeError as e:
                logging.error(f"JSON decoding error: {e}")
                return Response(str(e), mimetype='text/html', status=400)
        else:
            # Handle GET request with query parameters
            try:
                item_id = request.args.get('id')
                name = request.args.get('name')
                done = request.args.get('done') is not None

                if item_id and name:
                    new_id = next((item['id'] for item in data_store if item['name'] == name), None)
                    if new_id is None:
                        new_id = data_store[-1]['id'] + 1 if data_store else 1
                        new_item = {"id": new_id, "name": name, "done": done}
                        data_store.append(new_item)
                    else:
                        data_store[data_store.index({
                            'id': new_id,
                            'name': name
                        })]['done'] = done  # Update existing item

                return jsonify(data_store)

            except (KeyError, TypeError) as e:
                logging.error(f"Error processing query parameters: {e}")
                return Response("Invalid query parameters.", mimetype='text/html', status=400)

    return jsonify(data_store)


if __name__ == '__main__':
